export function inspectWorkspace(ws){validateWorkspace(ws);return{id:ws.id,title:ws.title,createdAt:ws.createdAt,revision:ws.revision,files:ws.files.map(({base64,...f})=>clone(f)),sources:clone(ws.sources),mappings:clone(ws.mappings),operatingProfiles:clone(ws.operatingProfiles),financialProfiles:clone(ws.financialProfiles),selections:clone(ws.selections),contracts:clone(ws.contracts),preparations:ws.preparations.map(({assessment,...p})=>({...clone(p),summary:clone(assessment.summary)})),returns:ws.returns.map(({comparison,...r})=>({...clone(r),summary:clone(comparison.summary),ready:comparison.ready})),reviews:ws.reviews.map(({report,...r})=>({...clone(r),summary:clone(report.summary)})),operations:clone(ws.operations)};}
